def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list) or len(items) != 1:
        return False
    if data.get("hasMore") is not True:
        return False
    cursor = data.get("nextCursor")
    if not isinstance(cursor, str) or not cursor:
        return False
    return bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list) or len(items) != 1:
        return False
    more = data.get("hasMore")
    cursor = data.get("nextCursor")
    if more is True:
        if not isinstance(cursor, str) or not cursor:
            return False
    elif more is False:
        if cursor is not None:
            return False
    else:
        return False
    return bool(responseBody.get("requestId"))

