def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list):
        return False
    t1 = globalParam.get("t1")
    t2 = globalParam.get("t2")
    t3 = globalParam.get("t3")
    if not (t1 and t2 and t3):
        return False
    def count(seq, target):
        n = 0
        for x in seq:
            if x == target:
                n += 1
        return n
    scan_ids = [item.get("id") for item in items if isinstance(item, dict)]
    if count(scan_ids, t1) != 1 or count(scan_ids, t2) != 1 or count(scan_ids, t3) != 1:
        return False
    walked = [globalParam.get("w" + str(i)) for i in range(1, 11)]
    walked = [x for x in walked if x]
    if count(walked, t1) != 1 or count(walked, t2) != 1 or count(walked, t3) != 1:
        return False
    if globalParam.get("hm10") is True:
        return False
    return bool(responseBody.get("requestId"))

